      steps++;

      if (!ent.alive) break;
      if (createRules(G, turnOpts).enemiesOf(ent).length === 0) break;
    }

    return {
      brain: firstBrain || String(opts.brain || ent.aiBrains || 'TACTICAL'),
      actions,
      unsupported,
      steps,
